using System;
using System.Collections.Generic;
using System.Linq;
using Tally.Billing;
using Tally.Domain;

namespace Tally.Api
{
    // Lists invoices that need a reminder.
    public class RemindersController
    {
        public IEnumerable<Invoice> DueToday(DateTime today)
        {
            return InvoiceCache.Items.Values.Where(i => i.Status == 3 && i.Due.Date == today.Date);
        }

        public IEnumerable<Invoice> Overdue()
        {
            return InvoiceCache.Items.Values.Where(i => i.Status == 5);
        }
    }
}
